curl -s -H "Authorization: Bearer glsa_JchCSUQxeULq1GCVuZQ9flcK4kMfrrBh_48b85734" \
  "https://jmsfortium.grafana.net/api/ds/query" \
  -H "Content-Type: application/json" \
  -d '{
    "queries": [{
      "datasource": {"type": "prometheus", "uid": "grafanacloud-jmsfortium-prom"},
      "expr": "{service_name=\"ensemble-vnext-test\"}",
      "instant": true,
      "refId": "A"
    }],
    "from": "now-1h",
    "to": "now"
  }' | jq '.results.A.frames[0].schema.fields[].name // "No data found"' 2>/dev/null || echo "Query failed or no data"

echo "=== Checking for any OTLP metrics ===" && curl -s -H "Authorization: Bearer glsa_JchCSUQxeULq1GCVuZQ9flcK4kMfrrBh_48b85734" \
  "https://jmsfortium.grafana.net/api/ds/query" \
  -H "Content-Type: application/json" \
  -d '{
    "queries": [{
      "datasource": {"type": "prometheus", "uid": "grafanacloud-jmsfortium-prom"},
      "expr": "up",
      "instant": true,
      "refId": "A"
    }],
    "from": "now-5m",
    "to": "now"
  }' | jq '.results.A.status // .message // .' 2>/dev/null | head -20

echo "=== Checking Loki for logs ===" && curl -s -H "Authorization: Bearer glsa_JchCSUQxeULq1GCVuZQ9flcK4kMfrrBh_48b85734" \
  "https://jmsfortium.grafana.net/api/ds/query" \
  -H "Content-Type: application/json" \
  -d '{
    "queries": [{
      "datasource": {"type": "loki", "uid": "grafanacloud-jmsfortium-logs"},
      "expr": "{service_name=~\".*ensemble.*\"}",
      "refId": "A"
    }],
    "from": "now-1h",
    "to": "now"
  }' 2>&1 | jq '.' 2>/dev/null | head -30

