     1→#!/usr/bin/env node
     2→
     3→/**
     4→ * Wiggum Hook: Autonomous execution mode for /implement-trd.
     5→ *
     6→ * This hook fires on Stop events when --wiggum flag is active.
     7→ * It intercepts Claude's exit attempts and re-injects the implementation prompt
     8→ * until all tasks are complete or max iterations is reached.
     9→ *
    10→ * Named after Chief Wiggum from The Simpsons - persistent, doesn't give up easily.
    11→ *
    12→ * Environment Variables:
    13→ *   WIGGUM_ACTIVE         - Set to "1" to enable (must be set by implement-trd)
    14→ *   WIGGUM_MAX_ITERATIONS - Maximum iterations before allowing exit (default: 50)
    15→ *   WIGGUM_DEBUG          - Enable debug logging to stderr (default: "0")
    16→ *
    17→ * Hook Type: Stop
    18→ *   - Fires when Claude attempts to end the conversation
    19→ *   - Can block exit by returning continue: true with decision: "block"
    20→ *   - Re-injects the original prompt via the "reason" field
    21→ *
    22→ * Completion Detection (TRD-C404, TRD-C407):
    23→ *   1. Parse JSONL transcript for <promise>COMPLETE</promise> tag
    24→ *   2. Check implement.json for 100% task completion
    25→ *   3. Check if max iterations reached
    26→ *
    27→ * Safety (TRD-C406):
    28→ *   - Uses stop_hook_active flag to prevent infinite loops
    29→ *   - Flag is set when hook executes, cleared on allowed exit
    30→ *
    31→ * Output format (to stdout):
    32→ *   Block exit:
    33→ *     {"hookSpecificOutput":{"hookEventName":"Stop"},"continue":true,"decision":"block","reason":"...prompt..."}
    34→ *
    35→ *   Allow exit:
    36→ *     {"hookSpecificOutput":{"hookEventName":"Stop"},"continue":true}
    37→ *
    38→ * Exit codes:
    39→ *   0 - Hook processed successfully
    40→ */
    41→
    42→'use strict';
    43→
    44→const fs = require('fs');
    45→const path = require('path');
    46→
    47→// Constants
    48→const TRD_STATE_DIR = '.trd-state';
    49→const DEFAULT_MAX_ITERATIONS = 50;
    50→const COMPLETION_PROMISE_TAG = '<promise>COMPLETE</promise>';
    51→
    52→// State file for tracking iterations and preventing infinite loops
    53→const WIGGUM_STATE_FILE = '.trd-state/wiggum-state.json';
    54→const LOCK_FILE = '.trd-state/wiggum.lock';
    55→
    56→// Task status constants
    57→const TASK_STATUS = {
    58→  PENDING: 'pending',
    59→  IN_PROGRESS: 'in_progress',
    60→  SUCCESS: 'success',
    61→  COMPLETE: 'complete',
    62→  FAILED: 'failed',
    63→  BLOCKED: 'blocked'
    64→};
    65→
    66→// Cycle position constants
    67→const CYCLE_POSITION = {
    68→  IMPLEMENT: 'implement',
    69→  VERIFY: 'verify',
    70→  DEBUG: 'debug',
    71→  SIMPLIFY: 'simplify',
    72→  VERIFY_POST_SIMPLIFY: 'verify_post_simplify',
    73→  REVIEW: 'review',
    74→  UPDATE_ARTIFACTS: 'update_artifacts',
    75→  COMPLETE: 'complete'
    76→};
    77→
    78→/**
    79→ * Debug logging to stderr.
    80→ * Only outputs when WIGGUM_DEBUG=1.
    81→ * @param {string} msg - Message to log
    82→ */
    83→function debugLog(msg) {
    84→  if (process.env.WIGGUM_DEBUG === '1') {
    85→    const timestamp = new Date().toISOString();
    86→    console.error(`[WIGGUM ${timestamp}] ${msg}`);
    87→  }
    88→}
    89→
    90→/**
    91→ * Acquire a file lock to prevent concurrent execution.
    92→ * @param {string} projectRoot - Path to project root
    93→ * @returns {boolean} True if lock acquired, false otherwise
    94→ */
    95→function acquireLock(projectRoot) {
    96→  const lockPath = path.join(projectRoot, LOCK_FILE);
    97→  try {
    98→    // Check if lock exists and is stale (> 5 minutes old)
    99→    if (fs.existsSync(lockPath)) {
   100→      const stats = fs.statSync(lockPath);
   101→      const ageMs = Date.now() - stats.mtimeMs;
   102→      if (ageMs < 5 * 60 * 1000) {
   103→        debugLog('Lock file exists and is recent - another process may be running');
   104→        return false;
   105→      }
   106→      debugLog('Lock file is stale - removing');
   107→      fs.unlinkSync(lockPath);
   108→    }
   109→    // Create lock file with PID
   110→    fs.writeFileSync(lockPath, JSON.stringify({ pid: process.pid, timestamp: new Date().toISOString() }));
   111→    return true;
   112→  } catch (error) {
   113→    debugLog(`Error acquiring lock: ${error.message}`);
   114→    return false;
   115→  }
   116→}
   117→
   118→/**
   119→ * Release the file lock.
   120→ * @param {string} projectRoot - Path to project root
   121→ */
   122→function releaseLock(projectRoot) {
   123→  const lockPath = path.join(projectRoot, LOCK_FILE);
   124→  try {
   125→    if (fs.existsSync(lockPath)) {
   126→      fs.unlinkSync(lockPath);
   127→    }
   128→  } catch (error) {
   129→    debugLog(`Error releasing lock: ${error.message}`);
   130→  }
   131→}
   132→
   133→/**
   134→ * Validate and parse WIGGUM_MAX_ITERATIONS environment variable.
   135→ * @returns {number} Validated max iterations value
   136→ */
   137→function validateMaxIterations() {
   138→  const envValue = process.env.WIGGUM_MAX_ITERATIONS;
   139→  if (!envValue) {
   140→    return DEFAULT_MAX_ITERATIONS;
   141→  }
   142→  const parsed = parseInt(envValue, 10);
   143→  if (isNaN(parsed) || parsed < 1) {
   144→    debugLog(`Invalid WIGGUM_MAX_ITERATIONS: "${envValue}" - using default ${DEFAULT_MAX_ITERATIONS}`);
   145→    return DEFAULT_MAX_ITERATIONS;
   146→  }
   147→  if (parsed > 1000) {
   148→    debugLog(`WIGGUM_MAX_ITERATIONS capped at 1000 (was ${parsed})`);
   149→    return 1000;
   150→  }
   151→  return parsed;
   152→}
   153→
   154→/**
   155→ * Validate cwd input and return resolved absolute path.
   156→ * @param {string|undefined} inputCwd - Input cwd from hook data
   157→ * @returns {string|null} Validated cwd or null if invalid
   158→ */
   159→function validateCwd(inputCwd) {
   160→  const cwd = inputCwd || process.cwd();
   161→  // Resolve to absolute path
   162→  const resolved = path.resolve(cwd);
   163→  // Check it exists
   164→  if (!fs.existsSync(resolved)) {
   165→    debugLog(`CWD does not exist: ${resolved}`);
   166→    return null;
   167→  }
   168→  return resolved;
   169→}
   170→
   171→/**
   172→ * Find project root by walking up from cwd looking for .trd-state.
   173→ * @param {string} startDir - Directory to start search from
   174→ * @returns {string|null} Path to project root or null if not found
   175→ */
   176→function findProjectRoot(startDir) {
   177→  let currentDir = startDir;
   178→  const root = path.parse(currentDir).root;
   179→
   180→  while (currentDir !== root) {
   181→    const trdStatePath = path.join(currentDir, TRD_STATE_DIR);
   182→    if (fs.existsSync(trdStatePath) && fs.statSync(trdStatePath).isDirectory()) {
   183→      return currentDir;
   184→    }
   185→    currentDir = path.dirname(currentDir);
   186→  }
   187→
   188→  return null;
   189→}
   190→
   191→/**
   192→ * Read wiggum state file.
   193→ * @param {string} projectRoot - Path to project root
   194→ * @returns {Object} Wiggum state
   195→ */
   196→function readWiggumState(projectRoot) {
   197→  const statePath = path.join(projectRoot, WIGGUM_STATE_FILE);
   198→  try {
   199→    if (fs.existsSync(statePath)) {
   200→      const content = fs.readFileSync(statePath, 'utf-8');
   201→      return JSON.parse(content);
   202→    }
   203→  } catch (error) {
   204→    debugLog(`Error reading wiggum state: ${error.message}`);
   205→  }
   206→
   207→  // Default state
   208→  return {
   209→    iteration_count: 0,
   210→    stop_hook_active: false,
   211→    last_prompt: null,
   212→    started_at: null
   213→  };
   214→}
   215→
   216→/**
   217→ * Write wiggum state file atomically.
   218→ * Writes to a temp file first, then renames to prevent corruption.
   219→ * @param {string} projectRoot - Path to project root
   220→ * @param {Object} state - Wiggum state to write
   221→ */
   222→function writeWiggumState(projectRoot, state) {
   223→  const statePath = path.join(projectRoot, WIGGUM_STATE_FILE);
   224→  const tempPath = statePath + '.tmp.' + process.pid;
   225→  try {
   226→    const stateDir = path.dirname(statePath);
   227→    if (!fs.existsSync(stateDir)) {
   228→      fs.mkdirSync(stateDir, { recursive: true });
   229→    }
   230→    // Write to temp file first
   231→    fs.writeFileSync(tempPath, JSON.stringify(state, null, 2), 'utf-8');
   232→    // Atomic rename
   233→    fs.renameSync(tempPath, statePath);
   234→    debugLog(`Wrote wiggum state: iteration=${state.iteration_count}`);
   235→  } catch (error) {
   236→    // Clean up temp file if it exists
   237→    try { fs.unlinkSync(tempPath); } catch (e) { /* ignore */ }
   238→    debugLog(`Error writing wiggum state: ${error.message}`);
   239→  }
   240→}
   241→
   242→/**
   243→ * Find current.json to get the active TRD.
   244→ * @param {string} projectRoot - Path to project root
   245→ * @returns {Object|null} Current context or null
   246→ */
   247→function readCurrentJson(projectRoot) {
   248→  const currentPath = path.join(projectRoot, TRD_STATE_DIR, 'current.json');
   249→  try {
   250→    if (fs.existsSync(currentPath)) {
   251→      const content = fs.readFileSync(currentPath, 'utf-8');
   252→      return JSON.parse(content);
   253→    }
   254→  } catch (error) {
   255→    debugLog(`Error reading current.json: ${error.message}`);
   256→  }
   257→  return null;
   258→}
   259→
   260→/**
   261→ * Read implement.json for the active TRD.
   262→ * @param {string} projectRoot - Path to project root
   263→ * @returns {Object|null} Implementation state or null
   264→ */
   265→function readImplementJson(projectRoot) {
   266→  // First try to get from current.json
   267→  const current = readCurrentJson(projectRoot);
   268→  if (current && current.status) {
   269→    try {
   270→      const content = fs.readFileSync(path.join(projectRoot, current.status), 'utf-8');
   271→      return JSON.parse(content);
   272→    } catch (error) {
   273→      debugLog(`Error reading implement.json from current: ${error.message}`);
   274→    }
   275→  }
   276→
   277→  // Fallback: find any implement.json in .trd-state
   278→  const trdStateDir = path.join(projectRoot, TRD_STATE_DIR);
   279→  try {
   280→    const entries = fs.readdirSync(trdStateDir, { withFileTypes: true });
   281→    for (const entry of entries) {
   282→      if (entry.isDirectory()) {
   283→        const implementPath = path.join(trdStateDir, entry.name, 'implement.json');
   284→        if (fs.existsSync(implementPath)) {
   285→          const content = fs.readFileSync(implementPath, 'utf-8');
   286→          return JSON.parse(content);
   287→        }
   288→      }
   289→    }
   290→  } catch (error) {
   291→    debugLog(`Error searching for implement.json: ${error.message}`);
   292→  }
   293→
   294→  return null;
   295→}
   296→
   297→/**
   298→ * Check if all tasks in implement.json are complete (TRD-C407).
   299→ * @param {Object} implementData - Implementation state data
   300→ * @returns {Object} {done: boolean, completed: number, total: number}
   301→ */
   302→function checkTaskCompletion(implementData) {
   303→  if (!implementData || !implementData.tasks) {
   304→    return { done: false, completed: 0, total: 0 };
   305→  }
   306→
   307→  const tasks = implementData.tasks;
   308→  const taskIds = Object.keys(tasks);
   309→  const total = taskIds.length;
   310→
   311→  if (total === 0) {
   312→    return { done: true, completed: 0, total: 0 };
   313→  }
   314→
   315→  let completed = 0;
   316→  for (const taskId of taskIds) {
   317→    const task = tasks[taskId];
   318→    if (task.status === TASK_STATUS.SUCCESS || task.status === TASK_STATUS.COMPLETE) {
   319→      completed++;
   320→    }
   321→  }
   322→
   323→  const done = completed === total;
   324→  debugLog(`Task completion: ${completed}/${total} (${done ? 'DONE' : 'in progress'})`);
   325→
   326→  return { done, completed, total };
   327→}
   328→
   329→/**
   330→ * Check for completion promise in transcript (TRD-C404).
   331→ * @param {Object} hookData - Hook data from Claude
   332→ * @returns {boolean} True if completion promise found
   333→ */
   334→function checkCompletionPromise(hookData) {
   335→  // Check transcript_path if provided
   336→  if (hookData.transcript_path) {
   337→    try {
   338→      const transcriptContent = fs.readFileSync(hookData.transcript_path, 'utf-8');
   339→      if (transcriptContent.includes(COMPLETION_PROMISE_TAG)) {
   340→        debugLog('Found completion promise in transcript');
   341→        return true;
   342→      }
   343→    } catch (error) {
   344→      debugLog(`Error reading transcript: ${error.message}`);
   345→    }
   346→  }
   347→
   348→  // Check session_output if provided
   349→  if (hookData.session_output) {
   350→    if (hookData.session_output.includes(COMPLETION_PROMISE_TAG)) {
   351→      debugLog('Found completion promise in session output');
   352→      return true;
   353→    }
   354→  }
   355→
   356→  // Check messages array if provided
   357→  if (hookData.messages && Array.isArray(hookData.messages)) {
   358→    for (const msg of hookData.messages) {
   359→      if (msg.content && typeof msg.content === 'string') {
   360→        if (msg.content.includes(COMPLETION_PROMISE_TAG)) {
   361→          debugLog('Found completion promise in messages');
   362→          return true;
   363→        }
   364→      }
   365→    }
   366→  }
   367→
   368→  return false;
   369→}
   370→
   371→/**
   372→ * Build the re-injection prompt (TRD-C403).
   373→ * @param {number} iteration - Current iteration number
   374→ * @param {number} maxIterations - Maximum iterations
   375→ * @param {Object} completion - Completion status
   376→ * @param {Object} implementData - Implementation state
   377→ * @returns {string} Prompt to re-inject
   378→ */
   379→function buildReinjectionPrompt(iteration, maxIterations, completion, implementData) {
   380→  const { completed, total } = completion;
   381→  const remaining = total - completed;
   382→
   383→  // Get current phase and task info if available
   384→  let currentPhase = implementData?.phase_cursor || 1;
   385→  let currentTask = 'unknown';
   386→
   387→  if (implementData?.tasks) {
   388→    // Find first non-complete task
   389→    for (const [taskId, task] of Object.entries(implementData.tasks)) {
   390→      if (task.status !== TASK_STATUS.SUCCESS && task.status !== TASK_STATUS.COMPLETE) {
   391→        currentTask = taskId;
   392→        break;
   393→      }
   394→    }
   395→  }
   396→
   397→  const prompt = `
   398→[WIGGUM AUTONOMOUS MODE - Iteration ${iteration}/${maxIterations}]
   399→
   400→Status: ${completed}/${total} tasks complete (${remaining} remaining)
   401→Current Phase: ${currentPhase}
   402→Next Task: ${currentTask}
   403→
   404→Continue implementing the TRD. Do not stop until all tasks are complete.
   405→When all tasks are done, emit: <promise>COMPLETE</promise>
   406→
   407→Resume /implement-trd execution from where you left off.
   408→`.trim();
   409→
   410→  return prompt;
   411→}
   412→
   413→/**
   414→ * Output hook result to stdout.
   415→ * @param {boolean} block - Whether to block exit
   416→ * @param {string|null} reason - Reason/prompt for re-injection (if blocking)
   417→ */
   418→function outputResult(block, reason = null) {
   419→  const output = {
   420→    hookSpecificOutput: {
   421→      hookEventName: 'Stop'
   422→    },
   423→    continue: true
   424→  };
   425→
   426→  if (block && reason) {
   427→    output.decision = 'block';
   428→    output.reason = reason;
   429→  }
   430→
   431→  console.log(JSON.stringify(output));
   432→  process.exit(0);
   433→}
   434→
   435→/**
   436→ * Main hook logic.
   437→ * @param {Object} hookData - Hook data from stdin
   438→ */
   439→async function main(hookData) {
   440→  // 1. Check if wiggum mode is active
   441→  if (process.env.WIGGUM_ACTIVE !== '1') {
   442→    debugLog('Wiggum mode not active (WIGGUM_ACTIVE != 1)');
   443→    outputResult(false);
   444→    return;
   445→  }
   446→
   447→  debugLog('Wiggum mode is ACTIVE');
   448→
   449→  // 2. Validate and get working directory
   450→  const cwd = validateCwd(hookData.cwd);
   451→  if (!cwd) {
   452→    outputResult(false);
   453→    return;
   454→  }
   455→
   456→  // 3. Find project root
   457→  const projectRoot = findProjectRoot(cwd);
   458→
   459→  if (!projectRoot) {
   460→    debugLog('No project root found (no .trd-state directory)');
   461→    outputResult(false);
   462→    return;
   463→  }
   464→  debugLog(`Project root: ${projectRoot}`);
   465→
   466→  // 4. Acquire lock to prevent concurrent execution
   467→  if (!acquireLock(projectRoot)) {
   468→    debugLog('Could not acquire lock - skipping');
   469→    outputResult(false);
   470→    return;
   471→  }
   472→
   473→  // 5. Load wiggum state
   474→  const wiggumState = readWiggumState(projectRoot);
   475→
   476→  // 6. Check stop_hook_active safety flag (TRD-C406)
   477→  if (wiggumState.stop_hook_active) {
   478→    debugLog('stop_hook_active flag is set - preventing infinite loop');
   479→    // Clear the flag and allow exit
   480→    wiggumState.stop_hook_active = false;
   481→    writeWiggumState(projectRoot, wiggumState);
   482→    releaseLock(projectRoot);
   483→    outputResult(false);
   484→    return;
   485→  }
   486→
   487→  // 7. Get max iterations using validated function
   488→  const maxIterations = validateMaxIterations();
   489→  debugLog(`Max iterations: ${maxIterations}`);
   490→
   491→  // 8. Increment iteration count (TRD-C405)
   492→  wiggumState.iteration_count++;
   493→  const iteration = wiggumState.iteration_count;
   494→  debugLog(`Current iteration: ${iteration}`);
   495→
   496→  // 9. Check iteration bounds (TRD-C405)
   497→  if (iteration > maxIterations) {
   498→    debugLog(`Max iterations (${maxIterations}) reached - allowing exit`);
   499→    // Reset state for next run
   500→    wiggumState.iteration_count = 0;
   501→    wiggumState.stop_hook_active = false;
   502→    writeWiggumState(projectRoot, wiggumState);
   503→    releaseLock(projectRoot);
   504→    outputResult(false);
   505→    return;
   506→  }
   507→
   508→  // 10. Check for completion promise (TRD-C404)
   509→  if (checkCompletionPromise(hookData)) {
   510→    debugLog('Completion promise detected - allowing exit');
   511→    // Reset state
   512→    wiggumState.iteration_count = 0;
   513→    wiggumState.stop_hook_active = false;
   514→    writeWiggumState(projectRoot, wiggumState);
   515→    releaseLock(projectRoot);
   516→    outputResult(false);
   517→    return;
   518→  }
   519→
   520→  // 11. Check task completion in implement.json (TRD-C407)
   521→  const implementData = readImplementJson(projectRoot);
   522→  const completion = checkTaskCompletion(implementData);
   523→
   524→  if (completion.done) {
   525→    debugLog('All tasks complete - allowing exit');
   526→    // Reset state
   527→    wiggumState.iteration_count = 0;
   528→    wiggumState.stop_hook_active = false;
   529→    writeWiggumState(projectRoot, wiggumState);
   530→    releaseLock(projectRoot);
   531→    outputResult(false);
   532→    return;
   533→  }
   534→
   535→  // 12. Not done - set safety flag and block exit (TRD-C403, TRD-C406)
   536→  wiggumState.stop_hook_active = true;
   537→  if (!wiggumState.started_at) {
   538→    wiggumState.started_at = new Date().toISOString();
   539→  }
   540→  writeWiggumState(projectRoot, wiggumState);
   541→
   542→  // 13. Build re-injection prompt
   543→  const prompt = buildReinjectionPrompt(iteration, maxIterations, completion, implementData);
   544→  debugLog(`Blocking exit, re-injecting prompt (iteration ${iteration})`);
   545→
   546→  // 14. Release lock and output block decision with prompt
   547→  // Note: We release lock here because we're blocking exit - the next iteration
   548→  // will need to acquire the lock again
   549→  releaseLock(projectRoot);
   550→  outputResult(true, prompt);
   551→}
   552→
   553→// Read hook data from stdin
   554→let inputData = '';
   555→
   556→process.stdin.setEncoding('utf8');
   557→
   558→process.stdin.on('data', (chunk) => {
   559→  inputData += chunk;
   560→});
   561→
   562→process.stdin.on('end', async () => {
   563→  try {
   564→    const hookData = inputData.trim() ? JSON.parse(inputData) : {};
   565→    await main(hookData);
   566→  } catch (error) {
   567→    debugLog(`Fatal error: ${error.message}`);
   568→    // Non-blocking on errors - allow exit
   569→    outputResult(false);
   570→  }
   571→});
   572→
   573→// Handle case where stdin is empty or closed immediately
   574→process.stdin.on('error', (error) => {
   575→  debugLog(`stdin error: ${error.message}`);
   576→  outputResult(false);
   577→});
   578→
   579→// Export for testing
   580→module.exports = {
   581→  main,
   582→  findProjectRoot,
   583→  readWiggumState,
   584→  writeWiggumState,
   585→  readCurrentJson,
   586→  readImplementJson,
   587→  checkTaskCompletion,
   588→  checkCompletionPromise,
   589→  buildReinjectionPrompt,
   590→  debugLog,
   591→  acquireLock,
   592→  releaseLock,
   593→  validateMaxIterations,
   594→  validateCwd,
   595→  COMPLETION_PROMISE_TAG,
   596→  DEFAULT_MAX_ITERATIONS,
   597→  TASK_STATUS,
   598→  CYCLE_POSITION,
   599→  LOCK_FILE
   600→};
   601→

